// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Create a short-lived private upload intent
	// (POST /api/v1/attachment-upload-intents)
	CreateAttachmentUploadIntent(ctx context.Context, request CreateAttachmentUploadIntentRequestObject) (CreateAttachmentUploadIntentResponseObject, error)
	// Verify and persist an uploaded private object
	// (POST /api/v1/attachment-upload-intents/{intent_id}/confirm)
	ConfirmAttachmentUpload(ctx context.Context, request ConfirmAttachmentUploadRequestObject) (ConfirmAttachmentUploadResponseObject, error)
	// List active or recoverable attachments for one typed owner
	// (GET /api/v1/attachments)
	ListAttachments(ctx context.Context, request ListAttachmentsRequestObject) (ListAttachmentsResponseObject, error)
	// Move an attachment to the seven-day trash
	// (DELETE /api/v1/attachments/{attachment_id})
	TrashAttachment(ctx context.Context, request TrashAttachmentRequestObject) (TrashAttachmentResponseObject, error)
	// Authorize and create a short-lived signed download
	// (POST /api/v1/attachments/{attachment_id}/download)
	CreateAttachmentDownload(ctx context.Context, request CreateAttachmentDownloadRequestObject) (CreateAttachmentDownloadResponseObject, error)
	// Restore an attachment before permanent purge
	// (POST /api/v1/attachments/{attachment_id}/restore)
	RestoreAttachment(ctx context.Context, request RestoreAttachmentRequestObject) (RestoreAttachmentResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

